"""Compute-node final report from saved native pilot/observer recovery; no fits."""
import csv,json,math,statistics
from pathlib import Path
D=Path('reports/gaussian-native-pilot20-v3');summary=json.loads((D/'summary.json').read_text());fits=json.loads((D/'fits.json').read_text());resources=json.loads((D/'resource-records.json').read_text())
records=list(csv.DictReader((D/'records.csv').open()));original={(r['case'],int(r['rep']),int(r['target'])):r for r in csv.DictReader(Path('reports/campaign-gaussian/records.csv').open())}
ours=[r for r in records if r['engine'] in ['ours_cold','ours_warm']];maxown=max(abs(float(r[k])-float(original[(r['case'],int(r['rep']),int(r['target']))][k])) for r in ours for k in ['estimate','se','lower','upper','pvalue'])
maxss=0.;paired=0
for p in sorted(Path('outputs/gaussian-native-cert-v3').glob('*/*.sslasso.csv')):
 old=Path('outputs/gaussian-native')/p.parent.name/p.name
 if not old.exists():continue
 a=list(csv.DictReader(old.open()));b=list(csv.DictReader(p.open()));assert len(a)==len(b)==10
 for ra,rb in zip(a,b):
  assert ra['target']==rb['target'];maxss=max(maxss,max(abs(float(ra[k])-float(rb[k])) for k in ['estimate','lower','upper','pvalue']))
 paired+=1
qp=[]
for p in sorted(Path('outputs/gaussian-native-cert-v3').glob('*/*.sslasso.qp.csv')):
 rr=list(csv.DictReader(p.open()));qp.append(dict(case=p.parent.name,file=p.name,rows=len(rr),certified_rows=sum(r['certified'].lower()=='true' for r in rr),max_abs_gap=max(abs(float(r['gap'])) for r in rr),max_excess_constraint=max(float(r['residual'])-float(r['mu']) for r in rr)))
checks=dict(own_benchmark_rows=len(ours),max_own_campaign_difference=maxown,sslasso_recovered_pairs=paired,max_sslasso_native_output_difference=maxss,native_sslasso_qp_fits=len(qp),native_sslasso_all_rows_certified_fits=sum(r['certified_rows']==r['rows'] for r in qp),note='Observer recovery preserves native interval outputs; failed strict QP certificates are retained and not relabeled optimal.')
(D/'parity-and-certificates.json').write_text(json.dumps(checks,indent=2)+'\n');(D/'qp-summary.json').write_text(json.dumps(qp,indent=2)+'\n')
assert len(ours)==1200 and maxown<1e-10 and paired==60 and maxss<1e-10 and len(qp)==60
forecast={}
for scope,engines in [('three_core_native_methods',['hdi','EconML','sslasso','SIHR','hdm']),('three_core_exact_seven_timing_tasks',['ours_cold','ours_warm','hdi','EconML','sslasso','SIHR','hdm'])]:
 rr=[r for r in resources if r['engine'] in engines];cpu=sum(r['cpu_seconds'] for r in rr)/20*1000;proc=sum(r['process_seconds'] for r in rr)/20*1000
 forecast[scope]=dict(datasets_per_case=1000,cases=3,tasks_per_dataset=len(engines),consumed_cpu_hours=cpu/3600,summed_process_hours=proc/3600,ideal_process_wall_hours64cpu=proc/3600/64,planning_process_wall_hours64cpu_50pct_margin=proc/3600/64*1.5,cpus=64,memory_gib=128,max_observed_worker_rss_gib=max(r['max_rss_kib'] for r in rr)/1024**2,note='Conditional extrapolation from20datasets/case, excludes queue delay, future input generation, analysis and extra designs. Native tasks infer different numbers of slopes. Includes each measured process warmup. Expanded ten-design and matched-statistical campaigns are not forecast here.')
(D/'full1000-forecast.json').write_text(json.dumps(forecast,indent=2)+'\n')
lines=['# Gaussian competitor pilot: native defaults and production-policy timing','','EMPIRICAL. Twenty matched response datasets in each of Gaussian moderate/correlated/benign designs;60datasets,420fit tasks. All input hashes match the frozen1000-per-design own arm. This is a native/default pipeline comparison. The earlier fixed-penalty engine comparison remains a separate matched statistical exercise. hdi/EconML/sslasso infer all slopes; Julia, SIHR and hdm request ten targets.','','|Design|Method|Finite intervals /20|Strict checks /20|Active coverage ± MCSE (%)|Null type I ± MCSE (%)|Power (%)|Active length|Mean fit (s)|','|---|---|---:|---:|---:|---:|---:|---:|---:|']
for case in ['gaussian-moderate','gaussian-correlated','gaussian-benign']:
 for e in ['ours_warm','hdi','EconML','sslasso','SIHR','hdm']:
  a=next(r for r in summary if r['case']==case and r['engine']==e and r['role']=='active');n=next(r for r in summary if r['case']==case and r['engine']==e and r['role']=='null')
  def percent(v):return 'NA' if v is None else f'{100*v:.2f}'
  lines.append(f"|{case}|{e}|{a['interval_available']}|{a['strict_valid']}|{percent(a['coverage'])} ± {percent(a['coverage_mcse'])}|{percent(n['rejection'])} ± {percent(n['rejection_mcse'])}|{percent(a['rejection'])}|{a['length']:.4f}|{a['mean_fit_seconds']:.3f}|")
lines+=['','Coverage is conditional on finite returned native intervals, including convergence-warned or uncertified native results. Strict checks show availability after rejecting exposed convergence warnings and requiring the declared sslasso QP feasibility/gap tolerances. A good conditional coverage number does not repair failed availability. Dataset-level MCSE pools target roles within each dataset. Twenty datasets give imprecise calibration estimates. These data were not used to tune the frozen Julia default.','','Native sslasso uses its adaptive per-row mu search and bias-allowance intervals. Its native p-values need not be dual to those expanded intervals. Known author-source bugs were not patched here. The original certificate recorder lost M/G through an R environment-binding mistake after writing the native intervals; the observer-only recovery saves theta and corrects those bindings. All60 recovered point/interval outputs match the original saved outputs. See parity-and-certificates.json and qp-summary.json. A failed certificate is reported, not repaired by relabeling a native row optimal.','','The prior matched hdi/EconML comparison used the same initial/nodewise penalties and500slopes; EconML subtracts selected slopes from n in its noise denominator, while Julia/hdi also subtract an intercept degree of freedom. The certified sslasso component comparison used the documented diagonal correction and fixed shared penalty. Those results are not a timing comparison of the new automatic HC3 policy.','','Julia cold-fit timers include fitting compilation after package import. The complete cold process resource includes imports and file loading. Warm timers follow a small independent warmup; the warm process also includes a separate CV/initializer measurement, so its complete process time is not a pure single-fit startup measurement. Initial-CV component times are measured separately, not obtained by subtraction. Actual kernel times, process times and per-worker RSS are retained. Peak RSS is not simultaneous total job memory.','','Full-study resource estimates below cover only these three core designs and named tasks, with a50%planning margin. Expanded competitor1000-replication arms have not been launched at report creation.','','```json',json.dumps(forecast,indent=2),'```','','Recreation: gaussian-native-v1 canary, v2 required-library/observer diagnostics, v3 observer-only certificate recovery; same92300000 campaign inputs checked against originalFloat64-byte hashes. analyze-gaussian-native-v3.py pilot20-v3 20 then this script, on a Discovery compute node. All raw warnings, failed attempts, native output tables, theta/certificate records and worker receipts are retained.','']
(D/'RESULTS.md').write_text('\n'.join(lines));print(json.dumps(dict(checks=checks,forecast=forecast)))
